SELECT dc.descendant_id AS id, GROUP_CONCAT( a.dept_name ORDER BY dc.depth DESC SEPARATOR '/' ) AS dept_path FROM dept_closure dc INNER JOIN sys_dept a ON a.id = dc.ancestor_id WHERE dc.descendant_id IN
#{id}
GROUP BY dc.descendant_id

SELECT COUNT(1)
FROM dept_closure dc
WHERE dc.ancestor_id = #{ancestorId}
  AND dc.descendant_id = #{descendantId}
